import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Monthly Meetup Aug 2026","description":"","frontmatter":{"title":"Ceph Developer Monthly Meetup Aug 2026","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Developer_Monthly_Meetup_Aug_2026.md","filePath":"posts/2026/Ceph_Developer_Monthly_Meetup_Aug_2026.md","lastUpdated":null}'),r={name:"posts/2026/Ceph_Developer_Monthly_Meetup_Aug_2026.md"};function o(n,e,p,s,h,u){return t(),i("div",null,[...e[0]||(e[0]=[l('<p>I&#39;m organizing the meeting summary around four main discussion points: the Ceph Manager&#39;s scalability challenges and the proposed multi-process daemon approach, persisting audit messages in RADOS, issues with manager module loading, and RGW profiles for Ceph X capabilities. I&#39;ll tag this with Ceph, MON, RGW, and the Chinese tags for meeting notes and community updates.--- title: Ceph Developer Monthly Meetup Aug 2026 date: 2026-08-05 updated: 2026-08-06 tags:</p><ul><li>Ceph</li><li>RGW</li><li>RADOS</li><li>会议纪要</li><li>社区动态 categories:</li><li>视频总结 subtitle: Ceph_Developer_Monthly_Meetup_Aug_2026</li></ul><hr><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph Developer Monthly（CDM）以开放讨论的形式进行，会议开始时议程为空，主持人 Laura 邀请与会者临时提出希望讨论的议题。虽然本次会议大部分内容是为下次 CDM 预热的话题铺垫，但围绕 Ceph Manager 架构改造、审计（auditing）功能以及 RGW 权限（caps）自动化管理展开了较有价值的技术讨论。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="一、ceph-manager-的可扩展性与隔离问题" tabindex="-1">一、Ceph Manager 的可扩展性与隔离问题 <a class="header-anchor" href="#一、ceph-manager-的可扩展性与隔离问题" aria-label="Permalink to &quot;一、Ceph Manager 的可扩展性与隔离问题&quot;">​</a></h3><p>这是本次会议讨论最深入的话题，将作为下次 CDM 的重点议程之一。</p><p><strong>问题背景</strong></p><p>当前 Ceph Manager 采用 Python sub-interpreter（子解释器）机制，在单一进程内加载所有 manager module。这一设计最初由 John Spray 提出，期望子解释器能够良好演进，使各模块保持相对独立并自然工作。但现实情况是：</p><ul><li>Python 在 sandboxing（沙箱隔离）方面表现很差；</li><li>随时间引入的大量依赖库无法容忍从不同 sub-interpreter 中被多次加载；</li><li>存在过多的全局状态（global state），导致模块之间以意想不到的方式相互破坏。</li></ul><p><strong>模块加载串行化的问题</strong></p><p>与会者分享了此前提交的一个 PR 相关经验：当 manager 发生 failover（故障切换）时，模块是以类似&quot;传送带&quot;的方式一个接一个串行加载的。如果其中某个模块初始化或加载缓慢，会导致排在其后的所有模块无法及时加载完成。</p><p>该 PR 并未从根本上修复内部加载机制，而是采取了缓解措施：</p><ul><li>让 manager 发送更多关于自身可用性的 beacon（心跳信标）；</li><li>为所有模块的加载预留更多时间；</li><li>在模块未能及时加载时提供更清晰的错误提示信息。</li></ul><p>修复后相关问题已显著减少，但根因仍未解决。团队目前正在调研：为什么系统要采用一次加载一个模块的串行机制？背后的依赖原因是什么？是否可能改为并行加载？这些都还处于非常早期的探索阶段。此外，加载路径中还涉及 finisher threads（收尾线程），需要区分&quot;查找并定位 Python 模块文件&quot;与&quot;实际初始化模块&quot;这两个不同阶段。</p><p><strong>核心解决方案：多进程化 Manager</strong></p><p>讨论的核心共识方向是将 manager 改造为<strong>多进程 daemon</strong>，让每个 manager module 运行在独立的 sub-process 中。这样可以隔离由依赖引入的全局状态，避免模块之间相互影响，一举解决当前讨论中的多个问题。</p><p>关于是否应做成分布式系统尚有不同意见，但主流观点认为第一步不应做成分布式，只需先完成 manager 的多进程化即可。更进一步的期望是：将 Python 完全从主 manager 进程中剥离出来，仅在 module 进程中加载 Python 代码，让主 manager 退化为一个&quot;加强版的 monitor&quot;，负责向各 manager module 分发状态（distributing state），从而大幅简化架构。</p><p>与会者也提醒：由于该改造会顺带解决许多现有问题，因此应<strong>谨慎投入会被该方案顺带解决的其他修复工作</strong>，避免重复劳动。预计该工作会成为 Vampire 版本的优先事项，但目前尚未确定负责人。</p><h3 id="二、新的审计-auditing-功能" tabindex="-1">二、新的审计（Auditing）功能 <a class="header-anchor" href="#二、新的审计-auditing-功能" aria-label="Permalink to &quot;二、新的审计（Auditing）功能&quot;">​</a></h3><p>Ceph 即将新增审计功能。当前审计消息通常写入 Ceph monitor 本地文件系统的日志中，新功能将允许把审计消息持久化到 <strong>RADOS</strong> 中。</p><p>该功能特点：</p><ul><li>更加通用，可将任意数量的内容持久化到存储于 RADOS 中的 audit log channel（审计日志通道）；</li><li>由一名 IBM 实习生负责开发，Frankie 和 Daria 也参与其中；</li><li>工作仍在进行中，预计无法在下次 CDM 之前合并。</li></ul><h3 id="三、rgw-的-ceph-x-caps-profiles" tabindex="-1">三、RGW 的 Ceph X Caps Profiles <a class="header-anchor" href="#三、rgw-的-ceph-x-caps-profiles" aria-label="Permalink to &quot;三、RGW 的 Ceph X Caps Profiles&quot;">​</a></h3><p>针对近期合并的 RGW Ceph X caps profiles，与会者提出了关于存量转换的问题：现有 RGW caps 是否有自动转换方案，还是仅对未来新建的 RGW 生效？</p><p>答复要点：</p><ul><li>PR 作者表示其中包含了更新现有服务的 Cephadm 相关逻辑，看起来存量服务已被覆盖；</li><li>Rook 项目也在跟踪一种自动化实现方式；</li><li>更长远的目标是让 Rook 和 ceph-mgr 在每次 redeploy（重新部署）daemon 时，自动 rotate（轮换）密钥并同步更新所需的 caps，形成一套通用的自动化机制。当前该部分仍处于变动状态。</li></ul><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ul><li>将 <strong>Ceph Manager 可扩展性与隔离问题</strong>、<strong>审计功能</strong>两项议题写入 backlog，作为下次 CDM 的重点议题。</li><li>Ceph Manager 多进程化被确认为解决当前多个模块加载与隔离问题的主方向，预计纳入 Vampire 版本。</li><li>提醒团队暂缓投入那些会被 manager 多进程化改造顺带解决的独立修复工作。</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>就 Manager 模块加载议题准备一次结构化的演示/讨论：由此前提交 PR 的成员介绍当时对模块加载路径的理解，并邀请参与 finisher threads 相关工作的成员一同讲解，会前将通过线下沟通梳理演示内容。</li><li>就 Ceph Manager 相关讨论，联系 Yuri 获取相关参与人员的完整名单（目前已知 Nitin 等人参与）。</li><li>就审计功能，与负责的 IBM 实习生沟通，可能在下次 CDM 做一个小型 demo；同时初步计划该实习生在 9 月芝加哥的活动上做展示（其实习在下次 CDM 前结束，届时人在 Michigan，前往芝加哥展示可行）。</li><li>持续推进 RGW caps 的自动化转换与密钥轮换机制，待方案稳定后在后续会议进一步讨论。</li></ul>',32)])])}const m=a(r,[["render",o]]);export{d as __pageData,m as default};
